// Pull latest changes from Git to preview workspace
// This syncs the preview with GitHub commits made by the AI
const ctx = $input.item.json;
const siteId = ctx.site?.id;

if (!siteId) {
  console.log('⚠️ No siteId found, skipping git pull');
  return [{ json: ctx }];
}

console.log(`🔄 Waiting 2s for GitHub to process commits...`);
// Small delay to ensure GitHub has processed all commits from the AI
await new Promise(resolve => setTimeout(resolve, 2000));

console.log(`🔄 Pulling latest changes for site ${siteId}...`);

try {
  const result = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/pull',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId }),
    timeout: 60000
  });
  console.log(`✅ Git pull successful for ${siteId}:`, result);
  return [{ json: ctx }];
} catch (e) {
  console.error(`❌ Git pull failed for ${siteId}:`, e.message);
  // Continue anyway - preview might have direct writes
  return [{ json: ctx }];
}

const ctx = $('Merge Files').item.json;
const raw = $('AI Agent').item.json;

const output = raw?.output || '';
const steps = raw?.intermediateSteps || [];

const filesModified = new Set();
const filesCreated = new Set();
const filesDeleted = new Set();
const toolCalls = [];

for (const step of steps) {
  if (step.action?.tool) toolCalls.push(step.action.tool);
  const obs = step.observation || '';
  try {
    const result = JSON.parse(obs);
    if (result.success) {
      const file = result.file || result.to;
      if (file) {
        if (result.action === 'created') filesCreated.add(file);
        else if (result.action === 'updated') filesModified.add(file);
      }
      if (result.deleted) filesDeleted.add(result.deleted);
    }
  } catch {}
}

const warnings = [];
if (filesModified.size === 0 && filesCreated.size === 0 && filesDeleted.size === 0 && steps.length > 2) {
  warnings.push('No files were modified');
}

return [{
  json: {
    ...ctx,
    plan: { humanSummary: output, warnings },
    filesModified: [...filesModified],
    filesCreated: [...filesCreated],
    filesDeleted: [...filesDeleted],
    iterations: steps.length,
    toolsUsed: [...new Set(toolCalls)]
  }
}];

const rawInput = $fromAI('query', 'Package name', 'string') || '';
let pkg = rawInput.trim();

if (pkg.startsWith('{')) {
  try { const p = JSON.parse(pkg); pkg = p.package || p.name || p.input || ''; } catch {}
}

if (!pkg) return 'Error: Package name required';

const ctx = $('Merge Files')?.item?.json || {};
const siteId = ctx.site?.id;
if (!siteId) return 'Error: No site context';

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/preview/install',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ siteId, packages: [pkg] }),
    timeout: 120000
  });
  return JSON.stringify({ success: true, installed: response.installed || [pkg] });
} catch (e) {
  return 'Error: ' + e.message;
}

const rawInput = $fromAI('query', 'Search query', 'string') || '';
let query = rawInput.trim();

if (query.startsWith('{')) {
  try { const p = JSON.parse(query); query = p.query || p.input || ''; } catch {}
}

if (!query) return 'Error: Search query required';
if (query.length < 2) return 'Error: Query too short';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch, githubToken } = ctx;
if (!owner) return 'Error: No repository context';
if (!githubToken) return 'Error: No GitHub token provided';

try {
  // Get file tree
  const treeResponse = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  // Filter to source files only
  const sourceExts = ['.tsx', '.ts', '.jsx', '.js', '.css', '.html', '.json', '.md'];
  const files = (treeResponse.tree || [])
    .filter(f => f.type === 'blob' && sourceExts.some(ext => f.path.endsWith(ext)))
    .filter(f => !f.path.includes('node_modules') && !f.path.includes('.next'))
    .slice(0, 30);

  const matches = [];
  const queryLower = query.toLowerCase();

  // Search in files loaded in context first
  const contextFiles = ctx.fileContents || {};
  for (const [path, content] of Object.entries(contextFiles)) {
    if (content.toLowerCase().includes(queryLower)) {
      const lines = content.split('\n');
      for (let i = 0; i < lines.length; i++) {
        if (lines[i].toLowerCase().includes(queryLower)) {
          matches.push({ path, line: i + 1, text: lines[i].trim().substring(0, 60) });
          if (matches.length >= 10) break;
        }
      }
    }
  }

  // Search in other files if not enough matches
  if (matches.length < 10) {
    for (const file of files) {
      if (contextFiles[file.path]) continue; // Skip already searched
      try {
        const fileResponse = await this.helpers.httpRequest({
          method: 'GET',
          url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(file.path)}?ref=${branch}`,
          headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
          timeout: 5000
        });

        if (fileResponse.content) {
          const content = Buffer.from(fileResponse.content, 'base64').toString('utf8');
          if (content.toLowerCase().includes(queryLower)) {
            const lines = content.split('\n');
            for (let i = 0; i < lines.length; i++) {
              if (lines[i].toLowerCase().includes(queryLower)) {
                matches.push({ path: file.path, line: i + 1, text: lines[i].trim().substring(0, 60) });
                break; // One match per file
              }
            }
          }
        }
        if (matches.length >= 10) break;
      } catch {}
    }
  }

  if (matches.length > 0) {
    return 'Found "' + query + '" in ' + matches.length + ' location(s):\n' + 
      matches.map(m => `${m.path}:${m.line} - ${m.text}`).join('\n');
  }
  return 'No results for: "' + query + '"';
} catch (e) {
  return 'Error: ' + e.message;
}

const rawInput = $fromAI('query', 'File path', 'string') || '';
let filePath = rawInput.trim().replace(/^\/+/, '');

if (filePath.startsWith('{')) {
  try { const p = JSON.parse(filePath); filePath = p.path || p.input || ''; } catch {}
}

if (!filePath) return 'Error: File path required';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch, githubToken } = ctx;
if (!owner) return 'Error: No repository context';
if (!githubToken) return 'Error: No GitHub token provided';

try {
  const existing = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
    timeout: 10000
  });

  await this.helpers.httpRequest({
    method: 'DELETE',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: 'Delete ' + filePath, sha: existing.sha, branch }),
    timeout: 15000
  });

  return JSON.stringify({ success: true, deleted: filePath });
} catch (e) {
  return e.message.includes('404') ? 'Error: File not found: ' + filePath : 'Error: ' + e.message;
}

// Get raw input - format: filePath|||search|||replace
const rawInput = $fromAI('query', 'filePath|||search|||replace', 'string') || '';
const parts = rawInput.split('|||');
if (parts.length < 3) return 'Error: Use format filePath|||searchText|||replaceText';
const filePath = parts[0].trim().replace(/^\/+/, '');
const search = parts[1];
const replace = parts.slice(2).join('|||');
if (!filePath) return 'Error: filePath required';
if (!search) return 'Error: searchText required';
const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch, githubToken } = ctx;
const siteId = ctx.site?.id;
if (!owner) return 'Error: No repository context';
if (!githubToken) return 'Error: No GitHub token provided';

try {
  // Get current file
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  let content = Buffer.from(response.content, 'base64').toString('utf8');
  let matchedString = null;
  // Strategy 1: Exact Match
  if (content.includes(search)) {
    matchedString = search;
  } 
  // Strategy 2: Flexible Whitespace Match
  else {
    // Escape regex characters
    const escapeRegExp = (string) => string.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    // Split into lines and create a regex that ignores leading/trailing whitespace difference
    const searchLines = search.split(/\r?\n/).map(l => l.trim()).filter(l => l);

    if (searchLines.length > 0) {
       // Construct regex: match lines with any amount of whitespace in between
       const regexPattern = searchLines.map(line => {
         return '[\\t ]*' + escapeRegExp(line) + '[\\t ]*';
       }).join('\\r?\\n');

       const regex = new RegExp(regexPattern, 'g'); // Global to check match count
       const matches = content.match(regex);

       if (matches && matches.length === 1) {
         matchedString = matches[0];
       } else if (matches && matches.length > 1) {
         return 'Error: Ambiguous search. Found ' + matches.length + ' matches. Include more context.';
       }
    }
  }
  if (!matchedString) {
    const lines = content.split('\n');
    let hint = '';
    const searchLower = search.toLowerCase().substring(0, 20);
    // Simple similarity hint
    for (let i = 0; i < lines.length; i++) {
        if (lines[i].toLowerCase().includes(searchLower)) {
            hint = ` Similar line found at ${i+1}. Check whitespace/indentation.`;
            break;
        }
    }
    return 'Error: Search text not found. Try including more unique context lines.' + hint;
  }

  // Perform Replacement
  content = content.replace(matchedString, replace);

  // Update preview
  if (siteId) {
    this.helpers.httpRequest({
      method: 'POST',
      url: 'https://preview-orchestrator.fly.dev/preview/write',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ siteId, filePath, content }),
      timeout: 5000
    }).catch(() => {});
  }

  // Commit to GitHub
  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: 'Update ' + filePath, content: Buffer.from(content).toString('base64'), sha: response.sha, branch }),
    timeout: 30000
  });

  return JSON.stringify({ success: true, file: filePath, action: 'updated' });
} catch (e) {
  return e.message.includes('404') ? 'Error: File not found: ' + filePath : 'Error: ' + e.message;
}

// Get raw input - format: filePath|||content
const rawInput = $fromAI('query', 'filePath|||content', 'string') || '';
const parts = rawInput.split('|||');

if (parts.length < 2) return 'Error: Use format filePath|||content';

const filePath = parts[0].trim().replace(/^\/+/, '');
const content = parts.slice(1).join('|||'); // In case content has |||

if (!filePath) return 'Error: filePath required';

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch, githubToken } = ctx;
const siteId = ctx.site?.id;
if (!owner) return 'Error: No repository context';
if (!githubToken) return 'Error: No GitHub token provided';

try {
  // Update preview
  if (siteId) {
    this.helpers.httpRequest({
      method: 'POST',
      url: 'https://preview-orchestrator.fly.dev/preview/write',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ siteId, filePath, content }),
      timeout: 5000
    }).catch(() => {});
  }

  // Check if file exists
  let sha = null;
  try {
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
      headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
      timeout: 10000
    });
    sha = existing.sha;
  } catch {}

  const body = { message: (sha ? 'Update ' : 'Create ') + filePath, content: Buffer.from(content).toString('base64'), branch };
  if (sha) body.sha = sha;

  await this.helpers.httpRequest({
    method: 'PUT',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
    timeout: 30000
  });

  return JSON.stringify({ success: true, file: filePath, action: sha ? 'updated' : 'created' });
} catch (e) {
  return 'Error: ' + e.message;
}

// Get raw input string - it's just the file path
const rawInput = $fromAI('query', 'File path', 'string') || '';
let filePath = rawInput.trim();

// Clean up any wrapped formats
if (filePath.startsWith('{')) {
  try { const p = JSON.parse(filePath); filePath = p.path || p.input || p.filePath || ''; } catch {}
}
filePath = filePath.replace(/^\/+/, '');

if (!filePath) return 'Error: File path required. Just pass the path like: src/components/Header.tsx';

const ctx = $('Merge Files')?.item?.json || {};
if (ctx.fileContents?.[filePath]) return 'This file is ALREADY in context above. Look at FILES IN CONTEXT section.';

const { owner, repo, branch, githubToken } = ctx;
if (!owner) return 'Error: No repository context';
if (!githubToken) return 'Error: No GitHub token provided';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/contents/${encodeURIComponent(filePath)}?ref=${branch}`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  if (response.content) {
    const content = Buffer.from(response.content, 'base64').toString('utf8');
    return content.length > 6000 ? content.substring(0, 6000) + '\n// ... truncated' : content;
  }
  return 'Error: No content in response';
} catch (e) {
  return e.message.includes('404') ? 'Error: File not found: ' + filePath : 'Error: ' + e.message;
}

// Get raw input string
const rawInput = $fromAI('query', 'Directory path', 'string') || '.';
let path = rawInput.trim();

// Clean up any wrapped formats
if (path.startsWith('{')) {
  try { path = JSON.parse(path).path || JSON.parse(path).input || '.'; } catch { path = '.'; }
}

const ctx = $('Merge Files')?.item?.json || {};
const { owner, repo, branch, githubToken } = ctx;
if (!owner) return 'Error: No repository context';
if (!githubToken) return 'Error: No GitHub token provided';

try {
  const response = await this.helpers.httpRequest({
    method: 'GET',
    url: `https://api.github.com/repos/${owner}/${repo}/git/trees/${branch}?recursive=1`,
    headers: { 'Authorization': 'Bearer ' + githubToken, 'Accept': 'application/vnd.github+json' },
    timeout: 15000
  });

  const normalizedPath = path.replace(/^\/+/, '').replace(/\/+$/, '');
  let files = (response.tree || []).filter(f => f.type === 'blob').map(f => f.path);
  if (normalizedPath && normalizedPath !== '.') files = files.filter(f => f.startsWith(normalizedPath + '/'));

  return files.slice(0, 50).join('\n') || 'No files found in ' + path;
} catch (e) {
  return 'Error: ' + e.message;
}

const items = $input.all();
const prepItems = $('Prepare Fetch').all();
const ctx = prepItems[0]?.json?._ctx;
if (!ctx) throw new Error('Lost context');

const fileContents = {};
const contextFiles = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const path = prepItems[i]?.json?.currentFile || item.path;
  if (!path) continue;

  if (item.content) {
    try {
      const decoded = Buffer.from(item.content, 'base64').toString('utf8');
      fileContents[path] = decoded.length > 4000 ? decoded.substring(0, 4000) + '\n// ... truncated' : decoded;
      contextFiles.push(path);
    } catch (e) {}
  }
}

return [{ json: { ...ctx, fileContents, contextFiles } }];

const ctx = $('Build Context').item.json;
const files = ctx.filesToFetch || [];
if (files.length === 0) return [{ json: { ...ctx, currentFile: null } }];

return files.map(f => ({
  json: {
    _ctx: { ...ctx },
    currentFile: f,
    owner: ctx.owner,
    repo: ctx.repo,
    branch: ctx.branch,
    githubToken: ctx.githubToken
  }
}));

const inp = $('Validate & Detect Intent').item.json;
const rawSite = $input.first().json;

let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found for siteId: ' + inp.siteId);

// Extract GitHub Token: Prefer User Token, fallback to hardcoded System Token
const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

// Use siteKey for preview URL (subdomain-safe), fallback to site_key column or inp.siteId
const siteKey = site.site_key || inp.siteId;

const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

const owner = repoMatch[1];
const repo = repoMatch[2].replace(/\.git$/, '');
const msg = inp.message.toLowerCase();

const fileScores = new Map();
const addFile = (file, score) => fileScores.set(file, (fileScores.get(file) || 0) + score);

if (/shop|brand|name|title|logo/.test(msg)) {
  addFile('src/components/Header.tsx', 15);
  addFile('src/app/layout.tsx', 10);
  addFile('src/components/Footer.tsx', 8);
}
if (/color|theme|style|css|dark|light/.test(msg)) {
  addFile('src/app/globals.css', 10);
  addFile('tailwind.config.ts', 7);
}
if (/header|nav|menu/.test(msg)) addFile('src/components/Header.tsx', 12);
if (/footer/.test(msg)) addFile('src/components/Footer.tsx', 10);
if (/hero/.test(msg)) addFile('src/components/Hero.tsx', 10);
if (/page|home|landing/.test(msg) || fileScores.size === 0) addFile('src/app/page.tsx', 10);

const sortedFiles = [...fileScores.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([f]) => f);
if (sortedFiles.length === 0) sortedFiles.push('src/app/page.tsx');

return [{
  json: {
    ...inp,
    site: { id: siteKey, name: site.name || 'Unknown', repo_url: site.repo_url, branch: site.default_branch || 'main' },
    owner, repo,
    branch: site.default_branch || 'main',
    previewUrl: 'https://' + siteKey + '.preview.automatelb.com',
    filesToFetch: sortedFiles,
    fileContents: {},
    contextFiles: [],
    githubToken: githubToken
  }
}];

const b = $input.first().json.body || $input.first().json;

if (!b.siteId) throw new Error('Missing required field: siteId');
if (!b.message) throw new Error('Missing required field: message');

const msg = b.message.toLowerCase().trim();
const actionWords = /\b(implement|create|add|build|make|fix|update|change|edit|delete|remove|install|modify|replace|refactor|style|redesign|adjust|set|configure|enable|disable|write|code)\b/;
const questionWords = /^(what|why|how|can you|could you|should|is it|explain|describe|tell me)/;
const isQuestion = questionWords.test(msg);
const isActionIntent = actionWords.test(msg) && !isQuestion;

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    image: b.image || null,
    isActionIntent,
    isQuestion
  }
}];
